# BIOMOD 2026 - Pandora's Box
# Exploratory clinical and molecular characterization of
# CSPG4 expression in 44 primary acral melanomas.
#
# Expression: log2(TPM + 1), using original TPM values.
#
# This analysis reproduces the results presented at BIOMOD.
# It is exploratory, with a small sample size and no
# adjustment for potential clinical confounders.
#
# Individual-level clinical data are restricted.
# Full descriptive results must remain private when
# small subgroups could disclose individual expression.
#
# The official English figure is generated by script 14.

suppressPackageStartupMessages({
  library(ggplot2)
  library(brunnermunzel)
})

# Restore the original BIOMOD random number configuration.

RNGkind(
  kind = "L'Ecuyer-CMRG",
  normal.kind = "Inversion",
  sample.kind = "Rejection"
)

set.seed(20261022)

input_root <- getOption(
  "biomod.clinical.input_root", "."
)

output_dir <- getOption(
  "biomod.clinical.output_dir", "tables"
)

private_dir <- getOption(
  "biomod.clinical.private_dir",
  file.path(tempdir(), "biomod_clinical_private")
)

dir.create(
  output_dir,
  showWarnings = FALSE,
  recursive = TRUE
)

dir.create(
  private_dir,
  showWarnings = FALSE,
  recursive = TRUE,
  mode = "0700"
)

# 1. Effect sizes and confidence intervals ---------------------

cliff_delta <- function(x, y) {

  n1 <- length(x)
  n2 <- length(y)
  r <- rank(c(x, y))

  2 * ((sum(r[1:n1]) - n1 * (n1 + 1) / 2) /
         (n1 * n2)) - 1
}

bootstrap_ci <- function(x, y, B = 2000) {

  d <- replicate(B, cliff_delta(
    sample(x, replace = TRUE),
    sample(y, replace = TRUE)
  ))

  quantile(d, c(.025, .975))
}

# 2. Load original expression and clinical data ----------------

a <- read.csv(file.path(
  input_root,
  "results_v2/tables/nivelA_CSPG4_TPMcrudo_86muestras.csv"
))

a <- a[a$en_44, ]

clinical_metadata <- read.csv(
  file.path(
    input_root,
    "data/raw/acralMX_metadata_cc_update.csv"
  ),
  check.names = FALSE
)

d <- merge(
  a[, c("sample_id", "CSPG4_log2")],
  clinical_metadata,
  by = "sample_id"
)

stopifnot(nrow(d) == 44)

# Retrieve the transcriptomic cluster assignments.
# Preserve the original sample matching and cluster labels.

cluster_data <- read.csv(file.path(
  input_root,
  "results_v2/tables/nivelA_CSPG4_44muestras.csv"
))

cluster_columns <- grep(
  "cluster",
  names(cluster_data),
  ignore.case = TRUE,
  value = TRUE
)

if (
  !length(cluster_columns) ||
  !"sample_id" %in% names(cluster_data)
) {
  stop(
    "Missing cluster or sample_id column in the",
    " 44-sample expression table. Available columns: ",
    paste(names(cluster_data), collapse = ", ")
  )
}

d$cluster <- cluster_data[[cluster_columns[1]]][
  match(d$sample_id, cluster_data$sample_id)
]

stopifnot(!anyNA(d$cluster))

d$cluster <- factor(d$cluster)

d$stage_num <- as.numeric(d$stage)

d$ulc <- factor(
  d$ulceration,
  levels = c(0, 1),
  labels = c("No ulceration", "Ulceration")
)

# 3. Descriptive statistics -----------------------------------

describe_group <- function(var, label) {

  g <- split(
    d$CSPG4_log2,
    d[[var]],
    drop = TRUE
  )

  data.frame(
    variable = label,
    level = names(g),
    n = lengths(g),
    median = sapply(g, median),
    Q1 = sapply(g, quantile, .25),
    Q3 = sapply(g, quantile, .75),
    row.names = NULL
  )
}

desc <- rbind(
  describe_group("cluster", "cluster"),
  describe_group("stage", "stage"),
  describe_group("ulc", "ulceration"),
  describe_group("sex", "sex")
)

# Preserve the complete descriptive results privately.

write.csv(
  desc,
  file.path(
    private_dir,
    "clinical_descriptive_full.csv"
  ),
  row.names = FALSE
)

# Public disclosure safeguard:
# Do not export exact expression summaries for groups
# containing fewer than five observations.
#
# This affects disclosure only, not the statistical analysis.

public_desc <- desc

public_desc$summary_suppressed <- public_desc$n < 5

public_desc[
  public_desc$summary_suppressed,
  c("median", "Q1", "Q3")
] <- NA_real_

write.csv(
  public_desc,
  file.path(
    output_dir,
    "clinical_descriptive.csv"
  ),
  row.names = FALSE
)

# 4. Clinical association tests -------------------------------
# Four exploratory tests with Benjamini-Hochberg adjustment.

kw <- kruskal.test(
  CSPG4_log2 ~ cluster,
  data = d
)

n <- nrow(d)

sp <- cor.test(
  d$stage_num,
  d$CSPG4_log2,
  method = "spearman",
  exact = FALSE
)

# Ulceration: exclude missing observations.

dd <- d[!is.na(d$ulc), ]

x <- dd$CSPG4_log2[dd$ulc == "Ulceration"]
y <- dd$CSPG4_log2[dd$ulc == "No ulceration"]

bu <- brunnermunzel.test(x, y)
du <- cliff_delta(x, y)
iu <- bootstrap_ci(x, y)

# Sex: male versus female.
# Preserve the original contrast direction and bootstrap order.

xs <- d$CSPG4_log2[d$sex == "M"]
ys <- d$CSPG4_log2[d$sex == "F"]

bs <- brunnermunzel.test(xs, ys)
ds <- cliff_delta(xs, ys)
sex_ci <- bootstrap_ci(xs, ys)

# Preserve the original effect-size definitions.
# Cluster effect size: Kruskal-Wallis H / (n - 1).

res <- data.frame(
  variable = c(
    "cluster (3 groups)",
    "stage (0-4, ordinal)",
    "ulceration (present vs absent)",
    "sex (M vs F)"
  ),
  test = c(
    "Kruskal-Wallis",
    "Spearman",
    "Brunner-Munzel",
    "Brunner-Munzel"
  ),
  n = c(n, n, nrow(dd), n),
  effect_type = c(
    "epsilon^2",
    "Spearman rho",
    "Cliff's delta",
    "Cliff's delta"
  ),
  effect = c(
    unname(kw$statistic) / (n - 1),
    unname(sp$estimate),
    du,
    ds
  ),
  CI95_lower = c(
    NA, NA, iu[1], sex_ci[1]
  ),
  CI95_upper = c(
    NA, NA, iu[2], sex_ci[2]
  ),
  p = c(
    kw$p.value,
    sp$p.value,
    bu$p.value,
    bs$p.value
  )
)

res$p_BH <- p.adjust(res$p, method = "BH")

write.csv(
  res,
  file.path(
    output_dir,
    "clinical_association_tests.csv"
  ),
  row.names = FALSE
)

# 5. Exploratory pairwise cluster comparisons ------------------
#
# Benjamini-Hochberg adjustment across the three comparisons.
# These tests are separate from the four main clinical tests.

cluster_pairs <- combn(
  levels(d$cluster),
  2,
  simplify = FALSE
)

pairwise <- do.call(
  rbind,
  lapply(cluster_pairs, function(p) {

    u <- d$CSPG4_log2[d$cluster == p[1]]
    v <- d$CSPG4_log2[d$cluster == p[2]]

    data.frame(
      contrast = paste(p, collapse = " vs "),
      n1 = length(u),
      n2 = length(v),
      cliff_delta = cliff_delta(u, v),
      p_BM = brunnermunzel.test(u, v)$p.value
    )

  })
)

pairwise$p_BH_3pairs <- p.adjust(
  pairwise$p_BM,
  method = "BH"
)

write.csv(
  pairwise,
  file.path(
    output_dir,
    "clinical_cluster_pairwise.csv"
  ),
  row.names = FALSE
)

# 6. Consistency checks ----------------------------------------

stopifnot(
  nrow(d) == 44,
  nrow(dd) == 43,
  nlevels(d$cluster) == 3,
  nrow(res) == 4,
  nrow(pairwise) == 3,
  identical(
    as.integer(res$n),
    c(44L, 44L, 43L, 44L)
  )
)

stopifnot(isTRUE(all.equal(
  res$p_BH,
  p.adjust(res$p, "BH"),
  tolerance = 1e-10
)))

stopifnot(isTRUE(all.equal(
  pairwise$p_BH_3pairs,
  p.adjust(pairwise$p_BM, "BH"),
  tolerance = 1e-10
)))

cat("\n=== Clinical descriptive statistics ===\n")
print(public_desc, row.names = FALSE, digits = 5)

cat("\n=== Main clinical association tests ===\n")
print(res, row.names = FALSE, digits = 5)

cat("\n=== Exploratory cluster comparisons ===\n")
print(pairwise, row.names = FALSE, digits = 5)

cat(
  "\nPublic descriptive rows with suppressed summaries:",
  sum(public_desc$summary_suppressed),
  "\n"
)

cat(
  "\nNo individual-level clinical data were exported.\n"
)

cat(
  "The official English clinical figure is generated",
  "by script 14.\n"
)
